**Funciones sin tests:** `getPlanLimits`, `getGuzziModel`, `canUseGuzzi`, `canUseCamera`

**Casos no cubiertos:**
- Plan desconocido debe devolver `free` (fallback)
- Plan `null` y `undefined`
- String con mayúsculas (`"Pro"`, `"FREE"`)
- Todos los niveles de plan tienen los valores esperados

```typescript
// tests/unit/plan-limits.test.ts
import { describe, it, expect } from "vitest";
import { getPlanLimits, getGuzziModel, canUseGuzzi, canUseCamera, LIMITS } from "../../lib/plan-limits";

describe("getPlanLimits", () => {
  it("devuelve free para plan null", () => {
    expect(getPlanLimits(null)).toEqual(LIMITS.free);
  });

  it("devuelve free para plan undefined", () => {
    expect(getPlanLimits(undefined)).toEqual(LIMITS.free);
  });

  it("devuelve free para plan desconocido", () => {
    expect(getPlanLimits("premium_gold")).toEqual(LIMITS.free);
  });

  it("es case-insensitive — Pro → pro", () => {
    expect(getPlanLimits("Pro")).toEqual(LIMITS.pro);
  });

  it("devuelve límites correctos para empresa", () => {
    const l = getPlanLimits("empresa");
    expect(l.guzziMaxConsultasDia).toBeGreaterThanOrEqual(999999);
    expect(l.apiAccess).toBe(true);
  });
});

describe("canUseGuzzi", () => {
  it("permite guzzi en plan free (trial de 2)", () => {
    expect(canUseGuzzi("free")).toBe(true);
  });

  it("permite guzzi en plan pro", () => {
    expect(canUseGuzzi("pro")).toBe(true);
  });

  it("no permite guzzi con plan nulo — usa free", () => {
    expect(canUseGuzzi(null)).toBe(true); // free tiene 2 consultas
  });
});

describe("canUseCamera", () => {
  it.each(["free", "basico", "esencial", "pro", "empresa"])("plan %s puede usar cámara", (plan) => {
    expect(canUseCamera(plan)).toBe(true);
  });
});
```

