**Función sin tests:** `normalizar`

**Casos no cubiertos:**
- `aptitudes` como string con comas vs con saltos de línea
- `idiomas` vacío → default Español nivel 5
- `experiencia` como string en formato libre (regex parsing)
- `contacto` como string `"612345678, user@mail.com"` → split en teléfono/email
- Campos totalmente vacíos → strings vacíos, no undefined

```typescript
// tests/unit/normalizar.test.ts
import { describe, it, expect } from "vitest";
import { normalizar } from "../../lib/cv-generator/normalizar";

describe("normalizar — aptitudes", () => {
  it("parsea aptitudes como string separado por comas", () => {
    const cv = normalizar({ aptitudes: "Node.js, React, TypeScript" });
    expect(cv.aptitudes).toEqual(["Node.js", "React", "TypeScript"]);
  });

  it("parsea aptitudes como array ya formado", () => {
    const cv = normalizar({ aptitudes: ["Node.js", "React"] });
    expect(cv.aptitudes).toEqual(["Node.js", "React"]);
  });

  it("aptitudes vacío → array vacío", () => {
    const cv = normalizar({});
    expect(cv.aptitudes).toEqual([]);
  });
});

describe("normalizar — idiomas", () => {
  it("sin idiomas → default Español nivel 5", () => {
    const cv = normalizar({});
    expect(cv.idiomas).toEqual([{ nombre: "Español", nivel: 5 }]);
  });

  it("parsea idioma con nivel numérico: 'Inglés:80'", () => {
    const cv = normalizar({ idiomas: "Inglés:80, Francés:60" });
    expect(cv.idiomas[0]).toEqual({ nombre: "Inglés", nivel: 4 }); // 80/20 = 4
    expect(cv.idiomas[1]).toEqual({ nombre: "Francés", nivel: 3 }); // 60/20 = 3
  });

  it("nivel se clampea entre 1 y 5", () => {
    const cv = normalizar({ idiomas: "Chino:0" });
    expect(cv.idiomas[0].nivel).toBeGreaterThanOrEqual(1);
  });
});

describe("normalizar — contacto como string", () => {
  it("extrae teléfono y email del campo contacto", () => {
    const cv = normalizar({ contacto: "612345678, user@test.com" });
    expect(cv.telefono).toBe("612345678");
    expect(cv.email).toBe("user@test.com");
  });
});

describe("normalizar — campos vacíos", () => {
  it("nombre cae back a full_name", () => {
    const cv = normalizar({ full_name: "Ana García" });
    expect(cv.nombre).toBe("Ana García");
  });

  it("ciudad cae back a location", () => {
    const cv = normalizar({ location: "Madrid" });
    expect(cv.ciudad).toBe("Madrid");
  });
});
```

