**Funciones sin tests:** `checkRateLimit`, `isInBlacklist`, `addToBlacklist`, `getUserPlan`

**Casos no cubiertos:**
- Plan `empresa` → siempre permitido sin consultar DB
- Email de empresa en blacklist → bloqueado
- Límite diario alcanzado → `allowed: false`
- Límite mensual alcanzado → `allowed: false`
- Plan desconocido → fallback a `free`

```typescript
// tests/unit/rate-limiter.test.ts
import { describe, it, expect, vi, beforeEach } from "vitest";
import { checkRateLimit } from "../../lib/cv-sender/rate-limiter";

// Mock de Supabase
vi.mock("@supabase/supabase-js", () => ({
  createClient: () => ({
    from: () => ({
      select: () => ({
        eq: () => ({
          in: () => ({ gte: () => ({ count: 0 }) }),
          single: async () => ({ data: null, error: null }),
        }),
      }),
    }),
  }),
}));

describe("checkRateLimit — plan empresa", () => {
  it("plan empresa siempre devuelve allowed: true sin consultar DB", async () => {
    const result = await checkRateLimit("user-123", "empresa");
    expect(result.allowed).toBe(true);
    expect(result.limiteHoy).toBe(Infinity);
  });
});

describe("checkRateLimit — límite diario", () => {
  it("allowed: false cuando envíos hoy >= límite del plan", async () => {
    // Mock: 15 envíos hoy para plan "esencial" (límite 15/día)
    vi.mock("@supabase/supabase-js", () => ({
      createClient: () => ({
        from: () => ({
          select: () => ({
            eq: () => ({
              in: () => ({ gte: () => ({ count: 15 }) }),
            }),
          }),
        }),
      }),
    }));

    const result = await checkRateLimit("user-123", "esencial");
    expect(result.allowed).toBe(false);
    expect(result.reason).toContain("15");
  });
});
```

