**Función sin tests:** `isNativeIOS`

**Casos no cubiertos:**
- Entorno SSR (sin window) → `false`
- Capacitor presente pero en Android → `false`
- Capacitor presente en iOS → `true`

```typescript
// tests/unit/platform.test.ts
import { describe, it, expect, vi, afterEach } from "vitest";
import { isNativeIOS } from "../../lib/utils/platform";

afterEach(() => vi.restoreAllMocks());

describe("isNativeIOS", () => {
  it("devuelve false en SSR (sin window)", () => {
    const original = global.window;
    // @ts-expect-error
    delete global.window;
    expect(isNativeIOS()).toBe(false);
    global.window = original;
  });

  it("devuelve false si Capacitor no está presente", () => {
    expect(isNativeIOS()).toBe(false);
  });

  it("devuelve false si es Android", () => {
    (window as any).Capacitor = {
      isNativePlatform: () => true,
      getPlatform: () => "android",
    };
    expect(isNativeIOS()).toBe(false);
  });

  it("devuelve true si es iOS nativo", () => {
    (window as any).Capacitor = {
      isNativePlatform: () => true,
      getPlatform: () => "ios",
    };
    expect(isNativeIOS()).toBe(true);
  });
});
```

